-- Explicit user decisions2026-10-22, not an original reward-table claim.
--24Gem: one uniform original evolution fragment per chest/character/rolling24h.
--28unknown chests:100kamas once per chest/character. Original gates preserved.
--2missing-definition placements remain non-actionable until a real server route exists.
CREATE TABLE declared_treasure_policies (
 policy_id text PRIMARY KEY,reward_kind text NOT NULL CHECK(reward_kind IN ('uniform_fragment','kamas')),
 quantity integer NOT NULL,kamas bigint NOT NULL,cooldown_ms bigint NOT NULL,once_only boolean NOT NULL,
 authority text NOT NULL,sealed boolean NOT NULL DEFAULT false,
 CHECK((reward_kind='uniform_fragment' AND quantity=1 AND kamas=0 AND cooldown_ms=86400000 AND NOT once_only)
 OR (reward_kind='kamas' AND quantity=0 AND kamas=100 AND cooldown_ms=0 AND once_only))
);
CREATE TABLE declared_treasure_outcomes (
 policy_id text NOT NULL REFERENCES declared_treasure_policies,ordinal integer NOT NULL CHECK(ordinal>=0),
 item_reference integer NOT NULL CHECK(item_reference>0),source_authority text NOT NULL,
 PRIMARY KEY(policy_id,ordinal),UNIQUE(policy_id,item_reference)
);
CREATE TABLE declared_treasure_locations (
 map_id integer NOT NULL,object_id bigint NOT NULL,policy_id text NOT NULL REFERENCES declared_treasure_policies,
 native_family text NOT NULL CHECK(native_family IN ('LootChest','GenericActivableInteractiveElement')),
 descriptor_id integer NOT NULL,wire_action integer NOT NULL,requires_nonhero boolean NOT NULL,
 client_action_available boolean NOT NULL,source_disposition text NOT NULL,
 x integer NOT NULL,y integer NOT NULL,z integer NOT NULL,payload_hex text NOT NULL,state_payload_hex text NOT NULL,
 catalog_revision text NOT NULL CHECK(length(catalog_revision)=64),geometry_sha256 text NOT NULL CHECK(length(geometry_sha256)=64),
 approach_policy text NOT NULL CHECK(approach_policy='wakemu.reconstructed-cardinal-native-walkable.v1'),
 PRIMARY KEY(map_id,object_id),UNIQUE(policy_id,map_id,object_id)
);
CREATE TABLE declared_treasure_approaches (
 policy_id text NOT NULL,map_id integer NOT NULL,object_id bigint NOT NULL,x integer NOT NULL,y integer NOT NULL,z integer NOT NULL,
 PRIMARY KEY(map_id,object_id,x,y,z),
 FOREIGN KEY(policy_id,map_id,object_id) REFERENCES declared_treasure_locations(policy_id,map_id,object_id)
);
CREATE TABLE declared_treasure_attempts (
 token uuid PRIMARY KEY,account_id bigint NOT NULL,character_id bigint NOT NULL,map_id integer NOT NULL,object_id bigint NOT NULL,
 policy_id text NOT NULL,selected_ordinal integer,rule_digest text NOT NULL CHECK(length(rule_digest)=64),
 prepared_at timestamptz NOT NULL,completed_at timestamptz,receipt jsonb,
 FOREIGN KEY(account_id,character_id) REFERENCES characters(account_id,id),
 FOREIGN KEY(policy_id,map_id,object_id) REFERENCES declared_treasure_locations(policy_id,map_id,object_id),
 FOREIGN KEY(policy_id,selected_ordinal) REFERENCES declared_treasure_outcomes(policy_id,ordinal),
 CHECK((completed_at IS NULL AND receipt IS NULL) OR (completed_at IS NOT NULL AND receipt IS NOT NULL))
);
CREATE UNIQUE INDEX declared_treasure_pending_attempt ON declared_treasure_attempts(character_id,map_id,object_id) WHERE completed_at IS NULL;
CREATE TABLE declared_treasure_eligibility (
 character_id bigint NOT NULL,account_id bigint NOT NULL,map_id integer NOT NULL,object_id bigint NOT NULL,
 last_claimed_at timestamptz,pending_attempt uuid REFERENCES declared_treasure_attempts(token),
 PRIMARY KEY(character_id,map_id,object_id),
 FOREIGN KEY(account_id,character_id) REFERENCES characters(account_id,id),
 FOREIGN KEY(map_id,object_id) REFERENCES declared_treasure_locations(map_id,object_id)
);
CREATE FUNCTION declared_treasure_policy_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.sealed THEN RAISE EXCEPTION 'Sealed declared treasure policy is immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;
CREATE TRIGGER declared_treasure_policy_immutable BEFORE UPDATE OR DELETE ON declared_treasure_policies FOR EACH ROW EXECUTE FUNCTION declared_treasure_policy_immutable();
CREATE FUNCTION declared_treasure_child_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE previous text;following text;
BEGIN
 IF TG_OP<>'INSERT' THEN previous:=OLD.policy_id; END IF;
 IF TG_OP<>'DELETE' THEN following:=NEW.policy_id; END IF;
 IF EXISTS(SELECT 1 FROM declared_treasure_policies WHERE sealed AND policy_id IN(previous,following)) THEN
  RAISE EXCEPTION 'Sealed declared treasure content is immutable'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $$;
CREATE TRIGGER declared_treasure_outcomes_immutable BEFORE INSERT OR UPDATE OR DELETE ON declared_treasure_outcomes FOR EACH ROW EXECUTE FUNCTION declared_treasure_child_immutable();
CREATE TRIGGER declared_treasure_locations_immutable BEFORE INSERT OR UPDATE OR DELETE ON declared_treasure_locations FOR EACH ROW EXECUTE FUNCTION declared_treasure_child_immutable();
CREATE TRIGGER declared_treasure_approaches_immutable BEFORE INSERT OR UPDATE OR DELETE ON declared_treasure_approaches FOR EACH ROW EXECUTE FUNCTION declared_treasure_child_immutable();
UPDATE declared_treasure_policies SET sealed=true;
